import sys,tarfile,os,json,hashlib
from pathlib import Path
r=Path(sys.argv[1]);role=sys.argv[2];tar=Path('/var/tmp/owner-write-6d-'+role+'-text.tar');assert not tar.exists();files=[]
for rel in ['run','logs','results','evidence','config']:
 for f in (r/rel).rglob('*'):
  if f.is_file() and not f.is_symlink():
   b=f.read_bytes()
   if b'\0' not in b:files.append(f)
files.extend(f for f in (r/'etc').glob('*.toml') if f.is_file())
assert all(not __import__('re').search(rb'(?m)^-----BEGIN .*PRIVATE KEY-----$', f.read_bytes()) for f in files)
with tarfile.open(tar,'w') as a:
 for f in files:a.add(f,arcname=str(f.relative_to(r)),recursive=False)
tar.chmod(0o600);os.chown(tar,int(os.environ['SUDO_UID']),int(os.environ['SUDO_GID']))
print(json.dumps({'tar':str(tar),'sha256':hashlib.sha256(tar.read_bytes()).hexdigest(),'files':len(files),'bytes':sum(f.stat().st_size for f in files)}))
